export type Severity = "info" | "warning" | "error";

export type Notification = {
  id: string;
  severity: Severity;
  read: boolean;
  createdAt: number;
};

import { DurableObject } from "cloudflare:workers";

import type { Notification, Severity } from "./types";

const STORAGE_KEY = "notifications";

/**
 * Durable Object that is the source of truth for notifications.
 *
 * Notifications (and their read state) are stored in the Durable Object's
 * own durable storage, so they survive page reloads, worker restarts, and
 * Durable Object eviction/hibernation - there is no reliance on any
 * in-memory-only state.
 */
export class NotificationsDurableObject extends DurableObject {
  private async load(): Promise<Notification[]> {
    const stored = await this.ctx.storage.get<Notification[]>(STORAGE_KEY);
    return stored ?? [];
  }

  private async save(notifications: Notification[]): Promise<void> {
    await this.ctx.storage.put(STORAGE_KEY, notifications);
  }

  async list(): Promise<Notification[]> {
    return this.load();
  }

  async emit(severity: Severity): Promise<Notification[]> {
    const notifications = await this.load();
    const notification: Notification = {
      id: crypto.randomUUID(),
      severity,
      read: false,
      createdAt: Date.now(),
    };
    // Newest first.
    const next = [notification, ...notifications];
    await this.save(next);
    return next;
  }

  async markRead(id: string): Promise<Notification[]> {
    const notifications = await this.load();
    const next = notifications.map((notification) =>
      notification.id === id
        ? { ...notification, read: true }
        : notification,
    );
    await this.save(next);
    return next;
  }

  async markAllRead(): Promise<Notification[]> {
    const notifications = await this.load();
    const next = notifications.map((notification) => ({
      ...notification,
      read: true,
    }));
    await this.save(next);
    return next;
  }
}

import { env } from "cloudflare:workers";

import type { Notification, Severity } from "./types";

// Must match the default Durable Object name that `syncedStateRoutes` uses
// when no room id is present in the URL (see rwsdk's
// `DEFAULT_SYNC_STATE_NAME`). The notification center's client component
// calls `useSyncedState(initial, "notifications")` without a room id, so we
// need to target the same Durable Object instance here when broadcasting.
const SYNCED_STATE_ROOM = "syncedState";
const SYNCED_STATE_KEY = "notifications";

// A single, well-known Durable Object instance holds all notifications -
// this is a shared/global notification center, not scoped per-user.
const NOTIFICATIONS_ROOM = "global";

const getNotificationsStub = () => {
  const id = env.NOTIFICATIONS_DURABLE_OBJECT.idFromName(NOTIFICATIONS_ROOM);
  return env.NOTIFICATIONS_DURABLE_OBJECT.get(id);
};

const getSyncedStateStub = () => {
  const id = env.SYNCED_STATE_SERVER.idFromName(SYNCED_STATE_ROOM);
  return env.SYNCED_STATE_SERVER.get(id);
};

const broadcast = async (notifications: Notification[]) => {
  // Push the new canonical list to every connected client subscribed to the
  // "notifications" key - this is what makes the update show up live,
  // without a reload, on every open `/notifications` tab.
  await getSyncedStateStub().setState(notifications, SYNCED_STATE_KEY);
};

export const listNotifications = async (): Promise<Notification[]> => {
  return getNotificationsStub().list();
};

export const emitNotification = async (
  severity: Severity,
): Promise<Notification[]> => {
  const notifications = await getNotificationsStub().emit(severity);
  await broadcast(notifications);
  return notifications;
};

export const markNotificationRead = async (
  id: string,
): Promise<Notification[]> => {
  const notifications = await getNotificationsStub().markRead(id);
  await broadcast(notifications);
  return notifications;
};

export const markAllNotificationsRead = async (): Promise<Notification[]> => {
  const notifications = await getNotificationsStub().markAllRead();
  await broadcast(notifications);
  return notifications;
};

"use server";

import {
  emitNotification as emitNotificationImpl,
  markAllNotificationsRead as markAllNotificationsReadImpl,
  markNotificationRead as markNotificationReadImpl,
} from "@/notifications/store";
import type { Severity } from "@/notifications/types";

// Server functions invoked from the client notification center. Each one
// mutates the durable, shared notification list (source of truth lives in
// NotificationsDurableObject) and then broadcasts the updated list through
// the synced-state Durable Object so every connected client updates live.

export async function emitNotification(severity: Severity) {
  return emitNotificationImpl(severity);
}

export async function markNotificationRead(id: string) {
  return markNotificationReadImpl(id);
}

export async function markAllNotificationsRead() {
  return markAllNotificationsReadImpl();
